import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
const INDEX_SHA=import.meta.env.VITE_REVIEW_ATLAS_SHA??'e90d1d5f4a06d989b3b26788ebbb0701c537cf791fb19ec580f2586886df04de';
const name=/^[a-zA-Z0-9][a-zA-Z0-9._-]*$/;
async function digest(bytes){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');}
async function get(path,maximum,signal,directory='atlas'){const r=await fetch(`${import.meta.env.BASE_URL}${directory}/${path}`,{cache:'no-store',signal});if(!r.ok)throw Error(`${path}: HTTP ${r.status}`);const n=Number(r.headers.get('content-length'));if(n>maximum)throw Error(`${path}: size limit`);const b=await r.arrayBuffer();if(b.byteLength>maximum)throw Error(`${path}: size limit`);return b;}
export async function loadIndex(signal){const b=await get('index.json',4*1024*1024,signal);if(await digest(b)!==INDEX_SHA)throw Error('Atlas index integrity mismatch');const x=JSON.parse(new TextDecoder().decode(b));if(x.schema!=='DICOM3D-semantic-atlas-1'||!Array.isArray(x.structures)||!Array.isArray(x.bundles))throw Error('Unsupported atlas index');const ids=new Map();for(const b of x.bundles){if(!name.test(b.id)||!name.test(b.url)||!name.test(b.manifestUrl)||!Number.isSafeInteger(b.byteLength)||b.byteLength>=1e8)throw Error('Invalid bundle descriptor');for(const id of b.structureIds){if(ids.has(id))throw Error(`Duplicate owner ${id}`);ids.set(id,b.id);}}if(ids.size!==x.structures.length||x.structures.some(p=>ids.get(p.id)!==p.bundleId))throw Error('Catalog ownership mismatch');if(x.sourceNative){x.sourceNative=await loadSourceCatalog(x.sourceNative,signal);const mappings=new Map(x.sourceNative.ownerMappings.map(m=>[m.id,m]));x.structures=x.structures.map(p=>({...p,...mappings.get(p.id)}));}return x;}
export async function loadSourceCatalog(d,signal,directory='atlas'){
 if(!d||!name.test(d.url)||!Number.isSafeInteger(d.byteLength)||d.byteLength>16*1024*1024)throw Error('Invalid source catalog descriptor');
 const bytes=await get(d.url,d.byteLength,signal,directory);if(bytes.byteLength!==d.byteLength||await digest(bytes)!==d.sha256)throw Error('Source catalog integrity mismatch');
 const c=JSON.parse(new TextDecoder().decode(bytes));if(c.schema!=='dicom3d-source-native-atlas-1'||!Array.isArray(c.atoms)||!Array.isArray(c.concepts))throw Error('Invalid source catalog');
 const ids=new Set(c.atoms.map(a=>a.id));if(ids.size!==c.atoms.length||new Set(c.concepts.map(a=>a.key)).size!==c.concepts.length||c.concepts.some(r=>r.atomIds.some(id=>!ids.has(id))))throw Error('Invalid source membership');return c;
}
export async function loadBundle(b,signal,directory='atlas'){const [mb,bytes]=await Promise.all([get(b.manifestUrl,8*1024*1024,signal,directory),get(b.url,b.byteLength,signal,directory)]);if(await digest(mb)!==b.manifestSha256)throw Error(`${b.id}: manifest integrity mismatch`);if(bytes.byteLength!==b.byteLength||await digest(bytes)!==b.sha256)throw Error(`${b.id}: geometry integrity mismatch`);const manifest=JSON.parse(new TextDecoder().decode(mb));if(manifest.asset?.sha256!==b.sha256||manifest.asset?.relative_filename!==b.url||JSON.stringify(manifest.reference.structures.map(x=>x.id))!==JSON.stringify(b.structureIds))throw Error(`${b.id}: manifest ownership mismatch`);if(signal.aborted)throw new DOMException('Cancelled','AbortError');const gltf=await new GLTFLoader().parseAsync(bytes,'');if(signal.aborted){disposeScene(gltf.scene);throw new DOMException('Cancelled','AbortError');}const expected=new Set(b.structureIds),seen=new Set();gltf.scene.traverse(node=>{if(expected.has(node.name)){if(seen.has(node.name))throw Error(`duplicate owner ${node.name}`);seen.add(node.name);node.userData.semanticId=node.name;}});if(seen.size!==expected.size){disposeScene(gltf.scene);throw Error(`${b.id}: incomplete owner mapping`);}return {scene:gltf.scene,manifest,bytes:b.byteLength};}
export function disposeScene(scene){const geoms=new Set(),mats=new Set(),textures=new Set();scene.traverse(n=>{if(n.geometry)geoms.add(n.geometry);for(const m of Array.isArray(n.material)?n.material:n.material?[n.material]:[]){mats.add(m);for(const v of Object.values(m))if(v?.isTexture)textures.add(v);}});textures.forEach(x=>x.dispose());mats.forEach(x=>x.dispose());geoms.forEach(x=>x.dispose());}
